    public static bool CanRefine(AssetKey key)
    {
        return key switch
        {
            AssetAnimationKey animation => CanRefineAnimation(animation),
            AssetSpriteKey sprite => CanRefineSprite(sprite),
            _ => throw new ArgumentOutOfRangeException(nameof(key), key, null)
        };
    }

    private static bool CanRefineSprite(AssetSpriteKey key)
    {
        return key switch
        {
            AssetSpriteKey.Bag => true,
            AssetSpriteKey.BattleBackground => true,
            AssetSpriteKey.BattleCorpse => true,
            AssetSpriteKey.BuildingIcon => true,
            AssetSpriteKey.CapitalBackground => true,
            AssetSpriteKey.CityShield => true,
            AssetSpriteKey.Ground => true,
            AssetSpriteKey.GroundBorder => true,
            AssetSpriteKey.ItemIcon => true,
            AssetSpriteKey.LordFace => true,
            AssetSpriteKey.MainMenuBackground => true,
            AssetSpriteKey.MainMenuBackgroundV2 => false,
            AssetSpriteKey.Mountain => true,
            AssetSpriteKey.RaceSelectionBackground => true,
            AssetSpriteKey.Road => true,
            AssetSpriteKey.Rod => true,
            AssetSpriteKey.RuinBanner => true,
            AssetSpriteKey.CityImage => true,
            AssetSpriteKey.CapitalImage => true,
            AssetSpriteKey.SiteImage => true,
            AssetSpriteKey.SpellIcon => true,
            AssetSpriteKey.StackBanner => true,
            AssetSpriteKey.ThiefActionImage => true,
            AssetSpriteKey.Tombstone => true,
            AssetSpriteKey.Tree => true,
            AssetSpriteKey.UnitEventPortrait => true,
            AssetSpriteKey.UnitFace => true,
            AssetSpriteKey.UnitPortrait => true,
            _ => throw new ArgumentOutOfRangeException(nameof(key), key, null)
        };
    }

    private static bool CanRefineAnimation(AssetAnimationKey key)
    {
        return key switch
        {
            AssetAnimationKey.BattleEffect.Attack attack => BattleEffects.Contains(attack),
            AssetAnimationKey.BattleEffect.Blister blister => BattleEffects.Contains(blister),
            AssetAnimationKey.BattleEffect.Death death => BattleEffects.Contains(death),
            AssetAnimationKey.BattleEffect.Heal heal => BattleEffects.Contains(heal),
            AssetAnimationKey.BattleEffect.Item item => BattleEffects.Contains(item),
            AssetAnimationKey.BattleEffect.LevelUp levelUp => BattleEffects.Contains(levelUp),
            AssetAnimationKey.BattleEffect.Status status => BattleEffects.Contains(status),
            AssetAnimationKey.BattleUnit => true,
            AssetAnimationKey.BattleUnitAura aura => BattleUnitAuras.Contains(aura),
            AssetAnimationKey.BattleUnitShadow => true,
            AssetAnimationKey.Capital => true,
            AssetAnimationKey.BattleBackgroundOverlay => true,
            AssetAnimationKey.CapitalBackgroundOverlay => true,
            AssetAnimationKey.CapitalBuilding => true,
            AssetAnimationKey.City => true,
            AssetAnimationKey.CityShadow => true,
            AssetAnimationKey.Cloud => true,
            AssetAnimationKey.Crystal => true,
            AssetAnimationKey.Cursor => true,
            AssetAnimationKey.Landmark => true,
            AssetAnimationKey.MainMenuBackgroundOverlay => true,
            AssetAnimationKey.MountainRemoveEffect => true,
            AssetAnimationKey.RaceSelectionBackgroundOverlay => true,
            AssetAnimationKey.Ruin => true,
            AssetAnimationKey.Site => true,
            AssetAnimationKey.SiteBanner => true,
            AssetAnimationKey.SiteShadow => true,
            AssetAnimationKey.StackBattleEffect => true,
            AssetAnimationKey.StackBoat => true,
            AssetAnimationKey.StackBoatShadow => true,
            AssetAnimationKey.StackCreateEffect => true,
            AssetAnimationKey.StackDestroyEffect => true,
            AssetAnimationKey.StackOwnerChangeEffect => true,
            AssetAnimationKey.StackSummonDestroyEffect => true,
            AssetAnimationKey.StackUnit => true,
            AssetAnimationKey.StackUnitAura => true,
            AssetAnimationKey.StackUnitShadow => true,
            AssetAnimationKey.Water => true,
            AssetAnimationKey.WaterLandmark => true,
            AssetAnimationKey.WorldSpellEffect => true,
            _ => throw new ArgumentOutOfRangeException(nameof(key), key, null)
        };
    }
